import React, { useState, useRef, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  FileText,
  Upload,
  Mic,
  MicOff,
  Volume2,
  VolumeX,
  Clipboard,
  FileUp,
  Loader2,
  Sparkles,
  X
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { useSpeechRecognition } from '@/hooks/useSpeechRecognition';
import { useTextToSpeech } from '@/hooks/useTextToSpeech';
import { useToast } from '@/hooks/use-toast';
import { VoiceWave } from '@/components/VoiceWave';
import { summarizeText } from '@/lib/openai';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
  SelectLabel,
  SelectGroup,
  SelectSeparator,
} from '@/components/ui/select';

const SummarizerPage = () => {
  const [inputText, setInputText] = useState('');
  const [summary, setSummary] = useState('');
  const [selectedModel, setSelectedModel] = useState('gpt-4o-mini');
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { isListening, transcript, startListening, stopListening, resetTranscript, isSupported: speechSupported } = useSpeechRecognition();
  const { speak, stop, isSpeaking, isSupported: ttsSupported } = useTextToSpeech();
  const { toast } = useToast();

  const handleSummarize = useCallback(async () => {
    if (!inputText.trim()) {
      toast({
        title: "No content",
        description: "Please provide text to summarize.",
        variant: "destructive",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const aiSummary = await summarizeText(inputText, selectedModel);
      setSummary(aiSummary);
      if (ttsSupported) {
        speak("Summary complete. I've simplified the medical information into easy-to-understand bullet points.");
      }
    } catch (err: any) {
      console.error('Summarization error', err);
      toast({
        title: 'Summarization failed',
        description: (err as Error)?.message || 'Unable to summarize at this time.',
        variant: 'destructive',
      });
    } finally {
      setIsProcessing(false);
    }
  }, [inputText, selectedModel, toast, ttsSupported, speak]);

  // Update input when voice transcript changes
  React.useEffect(() => {
    if (transcript && !isListening) {
      if (transcript.toLowerCase().includes('summarize')) {
        handleSummarize();
      } else {
        setInputText(prev => prev + ' ' + transcript);
      }
      resetTranscript();
    }
  }, [transcript, isListening, handleSummarize, resetTranscript]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setUploadedFile(file);

      // Read text content if it's a text file
      if (file.type === 'text/plain' || file.name.endsWith('.txt')) {
        const reader = new FileReader();
        reader.onload = (event) => {
          setInputText(event.target?.result as string || '');
        };
        reader.readAsText(file);
      } else {
        toast({
          title: "File uploaded",
          description: `${file.name} has been uploaded. For demo purposes, please paste the text content.`,
        });
      }
    }
  };

  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText();
      setInputText(text);
      toast({
        title: "Text pasted",
        description: "Content has been pasted from clipboard.",
      });
    } catch (error) {
      toast({
        title: "Paste failed",
        description: "Unable to access clipboard. Please paste manually.",
        variant: "destructive",
      });
    }
  };



  const handleReadSummary = () => {
    if (isSpeaking) {
      stop();
    } else if (summary) {
      speak(summary.replace(/[*ΓÇó]/g, ''));
    }
  };

  const handleVoiceToggle = () => {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  };

  const clearAll = () => {
    setInputText('');
    setSummary('');
    setUploadedFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <div className="h-screen flex flex-col">
      {/* Header */}
      <header className="flex-shrink-0 h-16 border-b border-border bg-card/50 backdrop-blur-lg flex items-center justify-between px-4 lg:px-6">
        <div className="flex items-center gap-3 ml-12 lg:ml-0">
          <div className="w-9 h-9 rounded-lg accent-gradient flex items-center justify-center">
            <FileText className="h-4 w-4 text-white" />
          </div>
          <div>
            <h1 className="font-semibold text-foreground">Info Summarizer</h1>
            <p className="text-xs text-muted-foreground hidden sm:block">Simplify medical documents</p>
          </div>
        </div>

        {(inputText || summary) && (
          <Button variant="ghost" size="sm" onClick={clearAll}>
            <X className="h-4 w-4 mr-2" />
            Clear All
          </Button>
        )}
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-auto p-4 lg:p-6">
        <div className="max-w-4xl mx-auto space-y-6">
          {/* Upload Section */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-card rounded-2xl border border-border p-6"
          >
            <h2 className="text-lg font-semibold text-foreground mb-4">Upload or Paste Document</h2>

            {/* File Upload Area */}
            <div
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-border rounded-xl p-8 text-center cursor-pointer hover:border-primary/50 hover:bg-muted/50 transition-colors mb-4"
            >
              <input
                ref={fileInputRef}
                type="file"
                accept=".txt,.pdf,.doc,.docx"
                onChange={handleFileUpload}
                className="hidden"
              />
              <Upload className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <p className="text-foreground font-medium mb-1">Drop files here or click to upload</p>
              <p className="text-sm text-muted-foreground">Supports TXT, PDF, DOC files</p>
              {uploadedFile && (
                <div className="mt-4 inline-flex items-center gap-2 bg-primary/10 text-primary px-3 py-1 rounded-lg">
                  <FileUp className="h-4 w-4" />
                  {uploadedFile.name}
                </div>
              )}
            </div>

            {/* Quick Actions */}
            <div className="flex flex-wrap gap-3 mb-4 items-center">
              <div className="w-48">
                <Select value={selectedModel} onValueChange={(val) => setSelectedModel(val)}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Model" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectLabel>Free Models (Open Source)</SelectLabel>
                      <SelectItem value="llama-3.3-70b">Llama 3.3 70B (Recommended)</SelectItem>
                      <SelectItem value="mixtral-8x7b">Mixtral 8x7B</SelectItem>
                      <SelectItem value="llama-3.1-8b">Llama 3.1 8B (Fast)</SelectItem>
                    </SelectGroup>
                    <SelectSeparator />
                    <SelectGroup>
                      <SelectLabel>Premium Models</SelectLabel>
                      <SelectItem value="gpt-4o-mini">GPT-4o Mini</SelectItem>
                      <SelectItem value="gpt-4o">GPT-4o</SelectItem>
                      <SelectItem value="cohere">Cohere</SelectItem>
                      <SelectItem value="gemini-2.0">Gemini 2.0</SelectItem>
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>

              <div className="flex-1" />

              <div className="flex flex-wrap gap-3 mb-4">
                <Button variant="outline" onClick={handlePaste}>
                  <Clipboard className="h-4 w-4 mr-2" />
                  Paste from Clipboard
                </Button>

                {speechSupported && (
                  <Button
                    variant={isListening ? 'destructive' : 'outline'}
                    onClick={handleVoiceToggle}
                  >
                    {isListening ? (
                      <>
                        <MicOff className="h-4 w-4 mr-2" />
                        Stop Recording
                      </>
                    ) : (
                      <>
                        <Mic className="h-4 w-4 mr-2" />
                        Voice Input
                      </>
                    )}
                  </Button>
                )}
              </div>

            </div>

            {/* Voice Listening Indicator */}
            {isListening && (
              <div className="bg-primary/10 rounded-xl p-4 mb-4">
                <div className="flex items-center justify-center gap-4">
                  <VoiceWave isActive={isListening} />
                  <span className="text-primary font-medium">Listening... Say "Summarize" when ready</span>
                </div>
              </div>
            )}

            {/* Text Input */}
            <Textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="Or paste your medical report, prescription, or discharge summary here..."
              className="min-h-[200px] text-base resize-none"
            />

            {/* Summarize Button */}
            <Button
              size="lg"
              className="w-full mt-4 accent-gradient text-white font-semibold"
              onClick={handleSummarize}
              disabled={isProcessing || !inputText.trim()}
            >
              {isProcessing ? (
                <>
                  <Loader2 className="h-5 w-5 mr-2 animate-spin" />
                  Processing...
                </>
              ) : (
                <>
                  <Sparkles className="h-5 w-5 mr-2" />
                  Summarize Document
                </>
              )}
            </Button>
          </motion.div>

          {/* Summary Result */}
          {summary && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-card rounded-2xl border border-border p-6"
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-foreground">Simplified Summary</h2>
                {ttsSupported && (
                  <Button variant="outline" size="sm" onClick={handleReadSummary}>
                    {isSpeaking ? (
                      <>
                        <VolumeX className="h-4 w-4 mr-2" />
                        Stop Reading
                      </>
                    ) : (
                      <>
                        <Volume2 className="h-4 w-4 mr-2" />
                        Read Aloud
                      </>
                    )}
                  </Button>
                )}
              </div>

              <div className="prose prose-invert max-w-none">
                <div className="bg-muted rounded-xl p-6 text-foreground whitespace-pre-wrap text-base leading-relaxed">
                  {summary}
                </div>
              </div>

              <p className="text-xs text-muted-foreground mt-4 text-center">
                This summary is AI-generated for educational purposes only. Always consult your healthcare provider for medical advice.
              </p>
            </motion.div>
          )}
        </div>
      </main>
    </div>
  );
};

export default SummarizerPage;
